data = {
'Delta': {'rev':61643,'fuel':10566,'sw':16161},
'United': {'rev':57063,'fuel':11756,'sw':16678},
'Southwest': {'rev':27483,'fuel':5812,'sw':12240},
'American': {'rev':54211,'fuel':11418,'sw':16021},
'Alaska': {'rev':11735,'fuel':2506,'sw':3588},
}
fuel_pct = {k: v['fuel']/v['rev']*100 for k,v in data.items()}
