print("Fuel % ranked low to high:")
for k,v in sorted(fuel_pct.items(), key=lambda x:x[1]):
    print(k, round(v,2))
print("\nSW&B % ranked low to high:")
for k,v in sorted(sw_pct.items(), key=lambda x:x[1]):
    print(k, round(v,2))

